import json
calls=[]
def c(p,r,ch,note=None,inst=None,vol=None,fx=None,param=None):
 d={'pattern':p,'row':r,'channel':ch}
 if note is not None:d['note']=note
 if inst is not None:d['instrument']=inst
 if vol is not None:d['volume']=vol
 if fx is not None:d['effect']=fx
 if param is not None:d['effect_param']=param
 calls.append({'name':'pattern_set_cell','arguments':d})
# note-offs before each pad chord and end-of-pattern; retrigger unaffected same row due channels.
for p in range(1,10):
 for r in [15,31,47,63]:
  for ch in [3,4,5]:c(p,r,ch,'OFF')
# stop lead/echo voices at phrase transition, helps clean arrangement boundary
for p in range(1,10):
 for ch in [0,1,2,6,7,12]:c(p,63,ch,'OFF')
# Pattern 0 chord changes at 16, stop just before; then all controlled at end
for ch in [3,4,5,12]:c(0,15,ch,'OFF')
# p10 mid-chord switch
for ch in [3,4,5,12]:c(10,15,ch,'OFF')
# p4 breakdown: lead gates to make calls breathe, but do not collide with next starts
for r in [3,7,11,17,21,25,31,35,39,45,51,57,63]:
 c(4,r,0,'OFF')
# add swell into key structural sections (channel 15 where available), placed row 56
for p in [1,4,6,8]: c(p,56,15,'C4',20,18)
# intentional break silence/impact around p7 entry: riser p6 and already crash p7
# subtle tracker chord arpeggio FX on long intro organ notes (0xy cycles semitones x/y; triad members differ)
for r in [0,16]:
 c(0,r,3,fx=0,param=0x37)
 c(0,r,4,fx=0,param=0x47)
# Note pattern_set overwrites only given attrs expected, not entire cell
json.dump(calls,open('/workspace/polish.json','w'));print(len(calls))
